"use client";

import { useState } from "react";
import { Download, FileText, Globe, ChevronRight } from "lucide-react";
import { motion, AnimatePresence } from "motion/react";
import { resumeVariants } from "@/lib/profile";
import { Section } from "@/components/ui/section";
import { SkeletonIframe } from "@/components/ui/skeleton";
import { ResumeViewInline } from "@/components/home/resume-view";
import { cn } from "@/lib/utils";

type ResumeTab = "pdf" | "web";

// resumeVariants[0] is always the master ("Sairam Resume").
// [1..4] are role-targeted — shown only when NEXT_PUBLIC_RESUME_VARIANTS="true".
const master = resumeVariants[0];
const otherVariants = resumeVariants.slice(1);

export default function ResumePage() {
  const [tab, setTab] = useState<ResumeTab>("web");
  const [pdfLoading, setPdfLoading] = useState(true);

  // Read flag inside function body — NOT at module scope — so vi.stubEnv works in tests.
  const showVariants = process.env.NEXT_PUBLIC_RESUME_VARIANTS === "true";

  return (
    <main className="flex-1">
      {/* ── Header + PDF/Web toggle ──────────────────────────────────────── */}
      <Section label="// résumé" title="Sairam Resume" titleAs="h1">
        <div className="mt-4 flex flex-wrap items-center justify-between gap-4">
          <p className="max-w-2xl text-fg-muted">
            One verified engineering record — view as a formatted web résumé or
            preview the PDF.
          </p>

          {/* Segmented PDF / Web toggle — matches ViewSwitcher pill pattern */}
          <div
            role="group"
            aria-label="Choose résumé format"
            className="relative inline-flex items-center rounded-full border border-border bg-bg-surface/80 p-0.5 backdrop-blur"
          >
            {(["pdf", "web"] as const).map((t) => {
              const active = tab === t;
              const Icon = t === "pdf" ? FileText : Globe;
              const label = t === "pdf" ? "PDF" : "Web";
              return (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTab(t)}
                  aria-pressed={active}
                  aria-label={`${label} résumé`}
                  className={cn(
                    "relative inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium transition-colors",
                    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-1 focus-visible:ring-offset-bg-base",
                    active ? "text-bg-base" : "text-fg-muted hover:text-fg",
                  )}
                >
                  {active && (
                    <motion.span
                      layoutId="resume-tab-pill"
                      aria-hidden="true"
                      className="absolute inset-0 z-0 rounded-full bg-accent"
                      transition={{
                        type: "spring",
                        stiffness: 420,
                        damping: 34,
                      }}
                    />
                  )}
                  <span className="relative z-10 inline-flex items-center gap-1.5">
                    <Icon size={14} aria-hidden="true" />
                    {label}
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      </Section>

      {/* ── Tab content — crossfades on switch ──────────────────────────── */}
      <AnimatePresence mode="wait">
        {tab === "pdf" ? (
          <motion.div
            key="pdf"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.2, ease: [0.21, 0.47, 0.32, 0.98] }}
          >
            {/* ── Master PDF preview ──────────────────────────────────────── */}
            {/* pt-0: the header Section above already contributes its own py-20/24
                bottom padding; stacking this Section's matching top padding on top of
                that left ~190px of dead space between the toggle row and this label. */}
            <Section label="// preview" title="" className="pt-0 sm:pt-0">
              <div className="mb-4 flex items-center justify-between">
                <p className="font-mono text-xs text-fg-subtle">
                  Viewing: <span className="text-accent">{master.label}</span>
                  <span className="ml-2 text-fg-subtle/60">{master.tag}</span>
                </p>
                <a
                  href={master.file}
                  download
                  className="inline-flex items-center gap-1.5 text-xs text-fg-muted transition-colors hover:text-accent"
                >
                  <Download size={13} /> Download PDF
                </a>
              </div>

              <div className="relative overflow-hidden rounded-xl border border-border">
                <AnimatePresence>
                  {pdfLoading && (
                    <motion.div
                      key="pdf-skeleton"
                      className="absolute inset-0 z-10"
                      initial={{ opacity: 1 }}
                      exit={{ opacity: 0 }}
                      transition={{ duration: 0.3 }}
                    >
                      <SkeletonIframe />
                    </motion.div>
                  )}
                </AnimatePresence>

                <iframe
                  src={master.file}
                  onLoad={() => setPdfLoading(false)}
                  className={cn(
                    "h-[80vh] w-full transition-opacity duration-300",
                    pdfLoading ? "opacity-0" : "opacity-100",
                  )}
                  title={`${master.label} résumé preview`}
                />
              </div>
            </Section>

            {/* ── Role-targeted variants — only rendered when flag is ON ──── */}
            {showVariants && (
              <Section label="// variants" title="" className="pt-0 sm:pt-0">
                <details className="group">
                  <summary className="flex cursor-pointer list-none items-center gap-2 text-sm text-fg-muted hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent">
                    <ChevronRight
                      size={14}
                      aria-hidden="true"
                      className="shrink-0 text-fg-subtle transition-transform group-open:rotate-90"
                    />
                    <span>Role-targeted variants</span>
                    <span className="ml-auto font-mono text-[10px] text-fg-subtle">
                      {otherVariants.length} available
                    </span>
                  </summary>

                  <div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
                    {otherVariants.map((v) => (
                      <div
                        key={v.file}
                        className="card-surface flex items-center justify-between p-4"
                      >
                        <div className="flex items-center gap-3">
                          <FileText
                            size={18}
                            className="shrink-0 text-fg-subtle"
                            aria-hidden="true"
                          />
                          <div>
                            <p className="text-sm font-medium text-fg">
                              {v.label}
                            </p>
                            <p className="text-xs text-fg-subtle">{v.tag}</p>
                          </div>
                        </div>
                        <a
                          href={v.file}
                          download
                          aria-label={`Download ${v.label} résumé`}
                          className="rounded p-1 text-fg-subtle transition-colors hover:text-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
                        >
                          <Download size={16} />
                        </a>
                      </div>
                    ))}
                  </div>
                </details>
              </Section>
            )}
          </motion.div>
        ) : (
          <motion.div
            key="web"
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.2, ease: [0.21, 0.47, 0.32, 0.98] }}
          >
            <ResumeViewInline />
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  );
}
import type { Metadata, Viewport } from "next";
import { Inter, JetBrains_Mono } from "next/font/google";
import "./globals.css";
import { Providers } from "@/components/providers";
import { SiteNav } from "@/components/site-nav";
import { SiteFooter } from "@/components/site-footer";
import { CommandPalette } from "@/components/command-palette";
import { AskPortfolio } from "@/components/ask-portfolio";
import { TalkModeMount } from "@/components/chat/talk-mode-mount";
import { AnvilInlinePanel } from "@/components/chat/anvil-inline-panel";
import { AnvilCoreSurface } from "@/components/chat/anvil-core-surface";
import { WakeWordController } from "@/components/chat/wake-word-controller";
import { ViewHint } from "@/components/view-hint";
import { EasterEggs } from "@/components/game/easter-eggs";
import { PersonJsonLd, WebSiteJsonLd, FaqJsonLd } from "@/components/json-ld";
import { Analytics } from "@vercel/analytics/next";
import { SpeedInsights } from "@vercel/speed-insights/next";
import { profile } from "@/lib/profile";
import { getDiscoveryBadgesEnabled } from "@/lib/flags";
import { OpenToWorkBanner } from "@/components/open-to-work-banner";
import { OPEN_TO_WORK } from "@/lib/writing-flags";

const sans = Inter({ variable: "--font-sans", subsets: ["latin"], display: "swap" });
const mono = JetBrains_Mono({ variable: "--font-mono", subsets: ["latin"], display: "swap" });

const siteUrl = "https://anvilry.vercel.app";

// Dark browser chrome (address bar / status bar) to match the site.
export const viewport: Viewport = {
  themeColor: "#07080d",
  colorScheme: "dark",
  viewportFit: "cover",
};

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: {
    default: `${profile.name} — ${profile.role}`,
    template: `%s — ${profile.name}`,
  },
  description: profile.headline,
  keywords: [
    "GenAI Engineer",
    "Backend Engineer",
    "LLM Agent Orchestration",
    "Multi-Agent Systems",
    "RAG",
    "Event-Driven Architecture",
    "Python",
    "Go",
    profile.name,
  ],
  authors: [{ name: profile.name, url: profile.links.github }],
  openGraph: {
    type: "website",
    url: siteUrl,
    title: `${profile.name} — ${profile.role}`,
    description: profile.headline,
    siteName: profile.name,
  },
  twitter: { card: "summary_large_image", title: `${profile.name} — ${profile.role}`, description: profile.headline, images: [siteUrl + "/opengraph-image"] },
  robots: { index: true, follow: true },
};

export default async function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  const discoveryBadgesEnabled = await getDiscoveryBadgesEnabled();
  // data-scroll-behavior="smooth": Next 16 no longer overrides scroll-behavior on navigation
  // by default. We set `scroll-behavior: smooth` in globals.css and rely on it for in-page
  // anchor nav (/#work, /#contact), so opt back in explicitly. This also silences the Next 16
  // dev warning. (Reduced-motion still forces `auto` via the CSS media query — the attribute
  // only opts into the override, it doesn't defeat that.)
  //
  // suppressHydrationWarning on the three root tags: browser extensions (locator/inspector,
  // Grammarly, dark-mode, password managers, etc.) inject attributes onto <html>/<head>/<body>
  // BEFORE React hydrates, which otherwise throws a hydration-mismatch warning (e.g. the
  // `data-locator-hook-status-message` a DOM-locator extension adds to <head>). This is a
  // client-only artifact — the server HTML is clean and real visitors are unaffected — so we
  // suppress it ONLY on these three elements. The flag does NOT cascade to children, so any
  // genuine mismatch inside the app still surfaces normally.
  return (
    <html
      lang="en"
      data-scroll-behavior="smooth"
      className={`${sans.variable} ${mono.variable} h-full`}
      suppressHydrationWarning
    >
      <head suppressHydrationWarning>
        <PersonJsonLd />
        <WebSiteJsonLd />
        <FaqJsonLd />
      </head>
      <body className="min-h-full flex flex-col antialiased" suppressHydrationWarning>
        {/* First focusable element — lets keyboard users skip the nav (WCAG 2.4.1). */}
        <a href="#main-content" className="skip-link">
          Skip to content
        </a>
        <Providers discoveryBadgesEnabled={discoveryBadgesEnabled}>
          <SiteNav />
          {OPEN_TO_WORK && <OpenToWorkBanner />}
          <div id="main-content" tabIndex={-1} className="flex flex-1 flex-col outline-none">
            {children}
          </div>
          <SiteFooter />
          <CommandPalette discoveryBadgesEnabled={discoveryBadgesEnabled} />
          <AskPortfolio />
          {/* Single global mount for the two-way talk-mode modal — opened from the
              Chat-view "Talk" button or the ⌘K command via a shared module store. */}
          <TalkModeMount />
          {/* Single global mount for the in-place "Anvil" voice panel — the Siri-style
              surface that expands from the header orb (desktop) instead of the modal.
              Self-gates on its store (renders null when closed). */}
          <AnvilInlinePanel />
          {/* The CORE minimal Siri surface — orb-only + result card, no panel chrome.
              Self-gates on its store; flag-gated at the trigger (ORB_EXPERIENCE=core). */}
          <AnvilCoreSurface />
          {/* Opt-in wake word (off by default). Renders its persistent "Listening"
              banner + kill switch only while active, and only on the voice views. */}
          <WakeWordController />
          <ViewHint />
          {/* Global "subtle delight" — console greeting + Konami reveal, every view. */}
          <EasterEggs />
        </Providers>
        <Analytics />
        <SpeedInsights />
      </body>
    </html>
  );
}
import type { Metadata } from "next";
import { Hero } from "@/components/home/hero";
import { FeaturedWork } from "@/components/home/featured-work";
import { FeaturedProjects } from "@/components/home/featured-projects";
import { Achievements } from "@/components/home/achievements";
import { Testimonials } from "@/components/home/testimonials";
import { Contact } from "@/components/home/contact";
import { ViewRouter } from "@/components/view-router";
import { GithubStatsStrip } from "@/components/github-stats-strip";
import { WritingPreview } from "@/components/home/writing-preview";
import { GITHUB_STATS_ENABLED } from "@/lib/writing-flags";

// Explicit query-stripped canonical (resolved absolute via layout's metadataBase).
// `/` is the only route that carries ?view=, and a literal self-canonical would
// canonicalize each ?view= variant to itself — so pin it to the bare path to
// collapse /?view=gamified and /?view=chat back to the bare site URL.
export const metadata: Metadata = {
  alternates: { canonical: "/" },
};

export default function Home() {
  // The Classic <main> is the SSG/SSR default — rendered on the server and passed
  // to ViewRouter as the always-present baseline. ViewRouter swaps in the Chat /
  // Gamified client views only when the visitor toggles, without a navigation.
  return (
    <ViewRouter>
      <main className="flex-1">
        <Hero />
        <FeaturedWork />
        <FeaturedProjects />
        {GITHUB_STATS_ENABLED && <GithubStatsStrip />}
        <Achievements />
        <WritingPreview />
        <Testimonials />
        <Contact />
      </main>
    </ViewRouter>
  );
}
@import "tailwindcss";

/*
  Design system — dark-technical "beast" base.
  Palette pairs deep ink backgrounds with an electric-cyan + violet accent,
  echoing the ContextOS/Graph-Forge dashboards. WCAG AA verified on bg-base.
*/
:root {
  /* surfaces */
  --bg-base: #07080d;        /* page background */
  --bg-surface: #0d0f17;     /* cards */
  --bg-elevated: #141826;    /* hovered / elevated */
  --border: #1f2433;
  --border-strong: #2c3346;

  /* text */
  --fg: #e9ecf5;             /* primary text — 14.8:1 on bg-base */
  --fg-muted: #9aa3b8;       /* secondary — 6.9:1 on bg-base (AA) */
  --fg-subtle: #747e99;      /* tertiary / captions — 4.7:1 on bg-base (WCAG AA) */

  /* accents */
  --accent: #38e1ff;         /* electric cyan — links, focus, graph edges */
  --accent-strong: #0fb8db;
  --violet: #a78bfa;         /* secondary accent — AI/agent motifs */
  --green: #4ade80;          /* metrics up / success */
  --amber: #fbbf24;          /* highlights */

  /* effects */
  --glow-accent: 0 0 0 1px color-mix(in oklab, var(--accent) 35%, transparent),
                 0 0 24px -4px color-mix(in oklab, var(--accent) 45%, transparent);
}

@theme inline {
  --color-bg-base: var(--bg-base);
  --color-bg-surface: var(--bg-surface);
  --color-bg-elevated: var(--bg-elevated);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-fg: var(--fg);
  --color-fg-muted: var(--fg-muted);
  --color-fg-subtle: var(--fg-subtle);
  --color-accent: var(--accent);
  --color-accent-strong: var(--accent-strong);
  --color-violet: var(--violet);
  --color-green: var(--green);
  --color-amber: var(--amber);

  --font-sans: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono), ui-monospace, "SF Mono", monospace;

  --radius-card: 14px;
}

* {
  border-color: var(--border);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  /* WCAG 2.2 SC 2.4.12 Focus Not Obscured: the sticky h-14 (3.5rem) header would
     otherwise cover a focused in-page anchor target. Pad the scroll position so the
     focused element lands below the header. */
  scroll-padding-top: 3.5rem;
  /* Defensive backstop: an un-contained overflowing descendant anywhere in the tree
     (e.g. a shrink-to-fit row wider than the viewport) would otherwise widen the whole
     document and cause page-level horizontal scroll/drag on mobile. Any element that
     genuinely needs horizontal scroll must opt in locally with its own overflow-x-auto
     container (see the articles filter bar) — this rule only clips the leak, it never
     hides content that has its own scroll container. */
  overflow-x: hidden;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

/*
  Hero entrance — pure CSS, runs on first paint with NO JS/hydration gate, so the
  above-the-fold hero is never invisible-then-faded-in (that caused a load flicker
  and delayed LCP). Below-the-fold sections still use the JS-gated <Reveal>.
*/
@keyframes hero-rise {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
.hero-rise {
  opacity: 0;
  animation: hero-rise 0.5s cubic-bezier(0.21, 0.47, 0.32, 0.98) forwards;
}
@media (prefers-reduced-motion: reduce) {
  .hero-rise { opacity: 1; animation: none; }
}

/* Terminal cursor — cosmetic blink; solid (no animation) under reduced-motion. */
@keyframes terminal-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
.terminal-cursor { animation: terminal-blink 1s steps(1) infinite; }
@media (prefers-reduced-motion: reduce) {
  .terminal-cursor { animation: none; opacity: 1; }
}

/* Terminal boot — one-time fade-in of the scrollback on mount (the "boot" feel).
   Text is fully in the DOM (screen-reader-safe); this only animates opacity. */
@keyframes terminal-boot { from { opacity: 0; } to { opacity: 1; } }
.terminal-boot { animation: terminal-boot 0.4s ease-out; }
@media (prefers-reduced-motion: reduce) {
  .terminal-boot { animation: none; }
}

/* Anvil header-orb idle — a FLUID, swirling, color-shifting Siri-style orb. The "metaball
   by blur+contrast" recipe: several conic-gradient color lobes painted on one pseudo, then
   fused by `filter: blur() contrast()` so they bleed + merge into liquid blobs (the contrast
   re-sharpens the blurred edges into rounded metaballs), with the conic `from` angle spun by
   a registered @property for the swirl, and a slow hue-rotate for the color shift — all in
   ONE filter chain (filter is a single property). PURE CSS, ZERO JS/rAF/WebGL/new-dep. COST:
   animating a @property angle is a per-frame MAIN-THREAD style-recalc + paint of the small
   ~38px pseudo (custom-property animation is NOT compositor-promoted) — negligible at this
   size and never the LCP element, but do NOT scale this recipe up while animated. The heavy
   3D orb only mounts inside the open voice surface. NOTE: NO mix-blend-mode — the conic
   layers self-fuse via overlap+contrast, which also sidesteps the WebKit backdrop-filter +
   descendant-blend glitch (bug 176830) under the header's backdrop-blur. isolation +
   overflow:hidden + translateZ(0) keep it on its own layer. Reduced-motion → a STATIC but
   still rich/fused orb (keeps blur+contrast — never `filter:none`, which would shatter the
   metaballs into hard arcs). Pre-Baseline browsers (Safari <16.4) ignore @property → the
   conic `from` is unset and the orb degrades to the solid `--accent-strong` disc + glow (a
   fine fallback, not the fused metaball). blur is tuned for the real 28px host, not a preview. */

@property --anvil-swirl {
  syntax: "<angle>";
  inherits: false;
  initial-value: 40deg;
}
@property --anvil-hue {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes anvil-swirl-spin { to { --anvil-swirl: 400deg; } }
@keyframes anvil-hue-drift { to { --anvil-hue: 360deg; } }
@keyframes anvil-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.06); }
}

.anvil-orb-idle {
  position: relative;
  isolation: isolate;          /* own stacking context (keeps the fuse off the header backdrop) */
  overflow: hidden;            /* clip the fused blobs to the orb circle */
  border-radius: 9999px;
  background: var(--accent-strong); /* base wash behind the metaballs */
  box-shadow: 0 0 12px -2px color-mix(in oklab, var(--accent) 65%, transparent);
  animation: anvil-breathe 3.6s ease-in-out infinite;
}
/* The fluid layer: 4 conic color lobes at distinct off-center origins + signed swirl
   multipliers, fused by blur+contrast into liquid metaballs, hue-rotated for the shift. */
.anvil-orb-idle::before {
  content: "";
  position: absolute;
  inset: -25%;
  border-radius: 9999px;
  transform: translateZ(0);    /* promote to its own layer (Safari backdrop-root guard) */
  background:
    conic-gradient(from calc(var(--anvil-swirl) * 2)  at 32% 38%, var(--accent) 0deg, transparent 110deg),
    conic-gradient(from calc(var(--anvil-swirl) * -3) at 68% 36%, var(--violet, #a78bfa) 0deg, transparent 120deg),
    conic-gradient(from calc(var(--anvil-swirl) * 1)  at 40% 70%, color-mix(in oklab, var(--accent) 80%, white) 0deg, transparent 100deg),
    conic-gradient(from calc(var(--anvil-swirl) * -2) at 64% 66%, var(--accent-strong) 0deg, transparent 130deg);
  /* blur tuned for the REAL 28px host (~1.4px ≈ 5% of diameter) — fuses the lobes without
     washing them into a uniform smear; contrast re-sharpens into rounded metaballs. */
  filter: blur(1.4px) contrast(4.5) hue-rotate(var(--anvil-hue));
  animation:
    anvil-swirl-spin 18s linear infinite,
    anvil-hue-drift 22s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .anvil-orb-idle,
  .anvil-orb-idle::before {
    animation: none;
  }
  /* Keep the fused metaballs (static): freeze the swirl at its balanced initial angle and
     KEEP blur+contrast (a one-time raster, free) + a fixed hue — never `filter: none`. */
  .anvil-orb-idle::before {
    filter: blur(1.4px) contrast(4.5) hue-rotate(0deg);
  }
}

body {
  background: var(--bg-base);
  color: var(--fg);
  font-family: var(--font-sans);
  /* Same backstop as html above — some mobile WebKit builds still rubber-band the body's
     own scrollable overflow even when the html root is clipped. Belt-and-suspenders only;
     the fix is containing overflow at its source (see the articles filter bar). */
  overflow-x: hidden;
  /* faint technical grid + radial accent wash */
  background-image:
    radial-gradient(60rem 40rem at 75% -10%, color-mix(in oklab, var(--violet) 9%, transparent), transparent 70%),
    radial-gradient(50rem 36rem at 5% 0%, color-mix(in oklab, var(--accent) 8%, transparent), transparent 70%),
    linear-gradient(to right, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 56px 56px, 56px 56px;
  background-attachment: fixed;
}

/* focus-visible: keyboard nav (a11y).
   The .no-focus-ring opt-out is for elements that carry their OWN focus affordance
   (e.g. the ⌘K search row's focus-within border) — needed because this rule is
   UNLAYERED and would otherwise always beat any Tailwind utility (utilities live in
   @layer, and unlayered CSS wins the cascade regardless of specificity). */
/* WCAG 2.2 SC 2.4.11 Focus Appearance: a 3px outline (≥2px min) with offset gives a
   focus indicator whose contrast area clears the threshold against any background. */
:focus-visible:not(.no-focus-ring) {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip-to-content link: visually hidden until focused, then the first interactive
   element so keyboard users can jump past the nav to the page content (a11y basic). */
.skip-link {
  position: fixed;
  top: 0.5rem;
  left: 0.5rem;
  z-index: 100;
  transform: translateY(-150%);
  transition: transform 0.15s ease;
  background: var(--bg-elevated);
  color: var(--fg);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
}
.skip-link:focus {
  transform: translateY(0);
}
@media (prefers-reduced-motion: reduce) {
  .skip-link {
    transition: none;
  }
}

::selection {
  background: color-mix(in oklab, var(--accent) 30%, transparent);
  color: #fff;
}

/* utility: subtle card */
.card-surface {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
}
.card-surface:hover {
  border-color: var(--border-strong);
  background: var(--bg-elevated);
}

/* utility: monospace terminal label */
.mono-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}

/*
  View transitions — cross-fade when switching the top-level view (Classic / Chat /
  Play / Developer). Driven from setViewInternal via document.startViewTransition.
  Only `view-body` cross-fades; `site-header` is its own group and is pinned (no
  animation) so the sticky nav stays put across a switch.
*/
/* Directional slide keyframes for view transitions (C-1 upgrade from plain cross-fade) */
@keyframes vt-slide-in-from-right  { from { transform: translateX(6%);  opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes vt-slide-in-from-left   { from { transform: translateX(-6%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes vt-slide-out-to-left    { from { transform: none; opacity: 1; } to { transform: translateX(-6%); opacity: 0; } }
@keyframes vt-slide-out-to-right   { from { transform: none; opacity: 1; } to { transform: translateX(6%);  opacity: 0; } }

/* Forward (classic→chat etc): new view slides in from right, old slides out left */
[data-view-dir="forward"]::view-transition-new(view-body)  {
  animation: vt-slide-in-from-right 0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
}
[data-view-dir="forward"]::view-transition-old(view-body)  {
  animation: vt-slide-out-to-left   0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
}

/* Backward (chat→classic etc): new view slides in from left, old slides out right */
[data-view-dir="backward"]::view-transition-new(view-body) {
  animation: vt-slide-in-from-left  0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
}
[data-view-dir="backward"]::view-transition-old(view-body) {
  animation: vt-slide-out-to-right  0.28s cubic-bezier(0.21, 0.47, 0.32, 0.98) both;
}
::view-transition-old(site-header),
::view-transition-new(site-header) {
  /* Pin the persistent chrome — don't fade it with the body. */
  animation: none;
  mix-blend-mode: normal;
}

/* Reduced-motion kill-switch (belt-and-suspenders — JS already skips the API for
   these users; this guarantees no cross-fade even if a transition is ever started). */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}

/* ── 404 glitch eyebrow ───────────────────────────────────────────────────────
   Organic text-glitch for the "// 404 :: route-not-found" label on not-found.tsx.
   Respects prefers-reduced-motion by skipping the animation entirely.             */
@keyframes glitch-text {
  0%, 92%, 100% { transform: none; opacity: 1; }
  93%           { transform: skewX(-6deg) translateX(3px); opacity: 0.85; }
  95%           { transform: skewX(4deg) translateX(-2px); opacity: 0.9; }
  97%           { transform: skewX(-2deg) translateX(1px); opacity: 0.95; }
}

.glitch-eyebrow {
  animation: glitch-text 4s infinite;
}

@media (prefers-reduced-motion: reduce) {
  .glitch-eyebrow { animation: none; }
}

/* ── CSS scroll-driven reveals ───────────────────────────────────────────────
   Native animation-timeline: view() ties the animation progress to when the
   element enters the viewport scroll-timeline. No JS, no rAF, runs on the
   compositor thread. Supported: Chrome 115+, Firefox 110+, Safari 15.4+.
   Pre-Baseline browsers: animation: none fallback (static opacity:1).
   Kill-switch: prefers-reduced-motion → snap to final state immediately.    */

@keyframes scroll-fade-up {
  from { opacity: 0; translate: 0 20px; }
  to   { opacity: 1; translate: 0 0; }
}

/* Base utility: fades up as the element enters the viewport. */
.scroll-reveal {
  animation: scroll-fade-up linear both;
  animation-timeline: view();
  animation-range: entry 0% entry 35%;
}

/* Staggered variants for grid cards (N = 1–6, delay = N × 60ms). */
.scroll-reveal-stagger-1 { animation-delay: 60ms;  }
.scroll-reveal-stagger-2 { animation-delay: 120ms; }
.scroll-reveal-stagger-3 { animation-delay: 180ms; }
.scroll-reveal-stagger-4 { animation-delay: 240ms; }
.scroll-reveal-stagger-5 { animation-delay: 300ms; }
.scroll-reveal-stagger-6 { animation-delay: 360ms; }

@media (prefers-reduced-motion: reduce) {
  .scroll-reveal,
  [class*="scroll-reveal-stagger"] {
    animation: none;
    opacity: 1;
    translate: none;
  }
}

/* ─────────────────────────────────────────────────────────────────────────────
   Skeleton / shimmer loading system
   Single keyframe drives the sweep; .skeleton-shimmer applies gradient + size.
   The cyan accent hint at 50% gives the "electric" quality matching the palette.
   Runs 100% on the compositor thread (only background-position changes).
   ───────────────────────────────────────────────────────────────────────────── */
@keyframes shimmer {
  0%   { background-position: -200% center; }
  100% { background-position:  200% center; }
}

.skeleton-shimmer {
  background: linear-gradient(
    90deg,
    color-mix(in oklab, var(--fg-subtle)  8%, transparent)  0%,
    color-mix(in oklab, var(--fg-subtle) 18%, transparent) 38%,
    color-mix(in oklab, var(--accent)     8%, transparent) 50%,
    color-mix(in oklab, var(--fg-subtle) 18%, transparent) 62%,
    color-mix(in oklab, var(--fg-subtle)  8%, transparent) 100%
  );
  background-size: 200% 100%;
  animation: shimmer 1.8s ease-in-out infinite;
  border-radius: inherit;
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-shimmer {
    animation: none;
    background: color-mix(in oklab, var(--fg-subtle) 10%, transparent);
  }
}

