"use client";

import dynamic from "next/dynamic";
import type { ReactNode } from "react";
import { useView } from "@/components/view-context";
import { isViewEnabled } from "@/lib/enabled-views";
import { SkeletonViewTransition } from "@/components/ui/skeleton";

/**
 * Swaps the top-level experience based on the active view.
 *
 * CLASSIC is passed as `children` (the server-rendered page) and is ALWAYS
 * mounted — it is the SSG/SSR output crawlers and no-JS visitors get, and the
 * recruiter-in-a-hurry default. We toggle its visibility with `hidden` rather
 * than unmounting, so switching back is instant and its scroll position survives.
 *
 * GAMIFIED, CHAT, and DEVELOPER are client-only, lazily imported on first
 * activation, and UNMOUNTED when not active. Unmounting (not hiding) the gamified
 * view is what lets its R3F canvas dispose the WebGL GL context — a hidden-but-live
 * context leaks GPU memory on low-end mobile.
 *
 * Each dynamic import now has a SkeletonViewTransition fallback — the orb-aesthetic
 * loading state shows while the JS bundle downloads on first activation.
 */
const ChatView = dynamic(() => import("@/components/chat/chat-view").then((m) => m.ChatView), {
  ssr: false,
  loading: () => <SkeletonViewTransition label="Loading Chat..." />,
});
const GameView = dynamic(() => import("@/components/game/game-view").then((m) => m.GameView), {
  ssr: false,
  loading: () => <SkeletonViewTransition label="Loading Play..." />,
});
const DeveloperView = dynamic(
  () => import("@/components/game/developer-view").then((m) => m.DeveloperView),
  {
    ssr: false,
    loading: () => <SkeletonViewTransition label="Loading Dev..." />,
  },
);
const AnvilView = dynamic(() => import("@/components/chat/anvil-view").then((m) => m.AnvilView), {
  ssr: false,
  loading: () => <SkeletonViewTransition label="Loading Voice..." />,
});
const ResumeView = dynamic(
  () => import("@/components/home/resume-view").then((m) => m.ResumeView),
  {
    ssr: false,
    loading: () => <SkeletonViewTransition label="Loading Résumé..." />,
  },
);

export function ViewRouter({ children }: { children: ReactNode }) {
  const { view, setView } = useView();

  return (
    <div style={{ viewTransitionName: "view-body" }}>
      {/* Classic — always mounted; the SSG default. Hidden (not unmounted) when inactive. */}
      <div hidden={view !== "classic"} aria-hidden={view !== "classic"}>
        {children}
      </div>

      {/* Each optional view is gated by the build-time NEXT_PUBLIC_ENABLED_VIEWS flag.
          If disabled, navigating to ?view=X stays on Classic (hidden=false above). */}
      {view === "chat" && isViewEnabled("chat") && <ChatView />}
      {view === "gamified" && isViewEnabled("gamified") && <GameView />}
      {view === "developer" && isViewEnabled("developer") && <DeveloperView />}
      {view === "voice" && isViewEnabled("voice") && <AnvilView onClose={() => setView("classic")} />}
      {/* Resume view — always enabled; no WebGL, no animations, print-optimized. */}
      {view === "resume" && isViewEnabled("resume") && <ResumeView />}
    </div>
  );
}
"use client";

import { useState } from "react";
import { Sparkles, Send } from "lucide-react";
import { useChat } from "@/components/chat/use-chat";
import { RECRUITER_CHIPS, STARTER_CHIPS } from "@/components/chat/chat-suggestions";
import { ChatMessages } from "@/components/chat/chat-messages";
import { MicButton } from "@/components/chat/mic-button";
import { TalkLaunchButton } from "@/components/chat/talk-launch-button";
import { FilePickerButton } from "@/components/chat/file-picker-button";
import { AttachmentPreviewStrip } from "@/components/chat/attachment-preview-strip";
import { ViewEscapeHatch } from "@/components/view-escape-hatch";
import { profile, impactMetrics } from "@/lib/profile";

/**
 * AI-CHAT view — a full "concierge console", not a bare chat box. Opens answer-
 * first: identity + impact strip + a persistent recruiter chip-rail so the
 * strongest-work / GenAI / impact answers are one tap. Reuses the existing Bedrock
 * backend (/api/chat -> streamWithFallback) untouched via the useChat transport.
 *
 * The escape hatch is the FIRST focusable element (never a keyboard trap). Full
 * a11y (aria-live announce-on-settle, Stop, pin-aware autoscroll) lands in 2.3.
 */
export function ChatView() {
  const { messages, send, stop, isStreaming, pendingFiles, setPendingFiles } = useChat();
  const [input, setInput] = useState("");
  const empty = messages.length === 0;

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    send(input, pendingFiles.length > 0 ? pendingFiles : undefined);
    setInput("");
    setPendingFiles([]);
  };

  const ask = (q: string) => {
    if (isStreaming) return;
    send(q, []);
    setInput("");
  };

  return (
    // Fixed height (not min-h): the console must be a BOUNDED flex container so the
    // transcript scrolls INTERNALLY. With only min-height the element is content-sized
    // and unbounded, so a tall conversation grows the document and the inner
    // overflow-y-auto never engages (the autoscroll snap then no-ops). `dvh` (not vh)
    // keeps the composer clear of iOS Safari's address bar.
    <main className="mx-auto flex h-[calc(100dvh-3.5rem)] w-full max-w-3xl flex-col px-6 py-6">
      <div className="flex items-center justify-between gap-3">
        <ViewEscapeHatch />
        <div className="flex items-center gap-3">
          {/* Hands-free voice conversation (modal surface; null on the 5th-view surface
              or unsupported browsers). */}
          <TalkLaunchButton />
          <p className="inline-flex items-center gap-1.5 font-mono text-xs uppercase tracking-widest text-accent">
            <Sparkles size={13} aria-hidden="true" /> AI Concierge
          </p>
        </div>
      </div>

      {/* Bordered "console" panel — frames the whole conversation so it reads as a
          contained concierge terminal, not scattered elements in an empty void. */}
      {/* min-h-0 lets this flex child shrink below its content so the transcript
          (the flex-1 child below) can own the overflow instead of pushing the page. */}
      <section className="mt-4 flex min-h-0 flex-1 flex-col rounded-2xl border border-border-strong bg-bg-surface/40 p-5 shadow-xl shadow-black/20 backdrop-blur sm:p-6">
      {/* Answer-first greeting + verified impact strip (recruiter visual triage).
          min-h-0 + overflow-y-auto + shrink: on a SHORT viewport this tall block (greeting +
          6-tile metric grid) must scroll WITHIN itself rather than push the composer out of
          the bordered console (it was a rigid flex sibling, so it shoved the composer + caption
          past the section border). It collapses to nothing once a conversation starts (empty). */}
      {empty && (
        <header className="min-h-0 shrink overflow-y-auto">
          <h1 className="text-2xl font-semibold tracking-tight">
            Ask me anything about {profile.name.split(" ")[0]}&apos;s work
          </h1>
          <p className="mt-2 max-w-xl text-sm text-fg-muted">
            Grounded in real projects and production systems — GenAI, backend, and open source.
            I answer in the first person and never invent details.
          </p>
          <dl className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
            {impactMetrics.map((m) => (
              <div key={m.label + m.sub} className="rounded-xl border border-border bg-bg-surface/60 px-3 py-2.5">
                {/* dt = term (the metric), dd = description (its value+context) */}
                <dt className="font-mono text-lg font-semibold text-fg">{m.value}</dt>
                <dd className="text-xs text-fg-muted">{m.label}</dd>
                <dd className="text-[11px] text-fg-subtle">{m.sub}</dd>
              </div>
            ))}
          </dl>
        </header>
      )}

      {/* Conversation. Grows to fill; messages + a11y live region live here (2.3). */}
      <ChatMessages messages={messages} isStreaming={isStreaming} />

      {/* Persistent recruiter chip-rail — one-tap strongest-work / impact paths.
          shrink-0: never let a short viewport compress the chips into the transcript. */}
      <div className="mt-4 shrink-0">
        <div className="flex flex-wrap gap-2" role="group" aria-label="Suggested questions">
          {RECRUITER_CHIPS.map((c) => (
            <button
              key={c}
              type="button"
              onClick={() => ask(c)}
              disabled={isStreaming}
              className="rounded-full border border-border px-3 py-1.5 text-xs text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
            >
              {c}
            </button>
          ))}
        </div>
        {empty && (
          <div className="mt-2 flex flex-wrap gap-2">
            {STARTER_CHIPS.map((c) => (
              <button
                key={c}
                type="button"
                onClick={() => ask(c)}
                disabled={isStreaming}
                className="rounded-full px-3 py-1.5 text-xs text-fg-subtle transition-colors hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
              >
                {c}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Pending attachment previews — rendered above the composer when files are queued.
          Returns null when empty so there is no layout shift. */}
      <AttachmentPreviewStrip
        files={pendingFiles}
        onRemove={(i) => setPendingFiles((prev) => {
          const removed = prev[i];
          if (removed?.previewUrl) URL.revokeObjectURL(removed.previewUrl);
          return prev.filter((_, idx) => idx !== i);
        })}
      />

      {/* Composer. shrink-0: the input the user types in must NEVER be compressed or
          pushed below the console border on a short viewport (it was escaping the section). */}
      <form onSubmit={onSubmit} className="mt-3 flex shrink-0 items-center gap-2">
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Ask about my work, projects, or what I'm looking for…"
          aria-label="Ask a question about Sairam"
          className="flex-1 rounded-xl border border-border bg-bg-base px-4 py-3 text-sm outline-none placeholder:text-fg-muted focus:border-accent focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-1 focus-visible:ring-offset-bg-base"
        />
        {/* Push-to-talk mic — renders only where Web Speech is supported (else nothing,
            the text input is untouched). Transcripts fill the input for review. */}
        <MicButton onText={setInput} disabled={isStreaming} />
        {/* File attachment picker — feature-flagged via NEXT_PUBLIC_MULTIMODAL_ATTACHMENTS.
            Defaults to disabled so the button only appears when explicitly enabled. */}
        {process.env.NEXT_PUBLIC_MULTIMODAL_ATTACHMENTS === "true" && (
          <FilePickerButton
            onFiles={(f) => setPendingFiles((prev) => [...prev, ...f].slice(0, 3))}
            disabled={isStreaming}
          />
        )}
        {isStreaming ? (
          <button
            type="button"
            onClick={stop}
            className="inline-flex h-11 items-center rounded-xl border border-border px-4 text-sm text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
          >
            Stop
          </button>
        ) : (
          <button
            type="submit"
            disabled={!input.trim() && pendingFiles.length === 0}
            aria-label="Send"
            className="inline-flex h-11 w-11 items-center justify-center rounded-xl bg-accent text-bg-base transition-opacity disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-1 focus-visible:ring-offset-bg-base"
          >
            <Send size={16} />
          </button>
        )}
      </form>
      <p className="mt-2 shrink-0 text-center text-[11px] text-fg-subtle">
        Grounded in real work · may simplify details
      </p>
      </section>
    </main>
  );
}
"use client";

import { useRef, useState } from "react";
import { TerminalSquare } from "lucide-react";
import { ViewEscapeHatch } from "@/components/view-escape-hatch";
import { Terminal } from "@/components/game/terminal/terminal";
import { TerminalOverlay } from "@/components/game/terminal/terminal-overlay";
import { DeveloperRail } from "@/components/game/developer-rail";
import { hasPersonalContent } from "@/lib/personal";

/**
 * DEVELOPER view — a focused, full-page terminal destination. The keyboard-native CLI
 * over the same canonical content, promoted to its own first-class view (reachable via
 * the nav switcher, ⌘K, the `developer` terminal command, and ?view=developer).
 *
 * Layout: on lg+ a two-zone grid — the terminal FILLS the column height (a real-tool
 * feel, no wasted void) beside a quiet recruiter rail (metrics + résumé + contact).
 * Below lg the rail drops and it's a single-column terminal (mobile byte-unchanged →
 * WCAG 1.4.10 reflow safe). Lazy + unmounted-when-inactive (see view-router.tsx). The
 * escape hatch is the FIRST focusable element (never a keyboard trap).
 */
export function DeveloperView() {
  const [termMax, setTermMax] = useState(false);
  const maximizeRef = useRef<HTMLButtonElement>(null);

  return (
    // Fixed height on lg+ (not just min-h): the terminal can only scroll INTERNALLY if
    // an ancestor is height-BOUNDED — with only min-height the chain grows past the
    // viewport and the document scrolls instead (same trap fixed on the chat view).
    // Mobile keeps min-h so a short terminal doesn't get awkwardly capped. dvh avoids
    // the iOS Safari address-bar jump.
    <main className="mx-auto flex min-h-[calc(100vh-3.5rem)] w-full max-w-6xl flex-col px-6 py-6 lg:h-[calc(100dvh-3.5rem)] lg:min-h-0">
      <div className="flex items-center justify-between gap-3">
        <ViewEscapeHatch />
        <p className="inline-flex items-center gap-1.5 font-mono text-xs uppercase tracking-widest text-accent">
          <TerminalSquare size={13} aria-hidden="true" /> Developer Mode
        </p>
      </div>

      {/* One concise heading (demoted) — the boot banner prints identity, so don't repeat. */}
      <header className="mt-6">
        <h1 className="text-base font-semibold tracking-tight">Query my work via the CLI</h1>
        <p className="mt-1 max-w-2xl text-sm text-fg-muted">
          A keyboard-native terminal over the same verified projects and systems. Type{" "}
          <code className="rounded bg-bg-surface px-1 py-0.5 font-mono text-xs text-fg">help</code>{" "}
          for commands, or try{" "}
          <code className="rounded bg-bg-surface px-1 py-0.5 font-mono text-xs text-fg">summary</code>,{" "}
          <code className="rounded bg-bg-surface px-1 py-0.5 font-mono text-xs text-fg">ls work</code>,{" "}
          <code className="rounded bg-bg-surface px-1 py-0.5 font-mono text-xs text-fg">about</code>.
        </p>
        {/* A quiet nudge so a curious visitor can DISCOVER the eggs (the personal-reveal
            commands are hidden from help by design). Only shown when there's real
            content to find — empty-safe, mirrors the whoami breadcrumb. Subtle enough to
            never distract the recruiter-in-a-hurry. */}
        {hasPersonalContent && (
